import { describe, expect, test } from 'bun:test';
import {
    ASSESSMENT_PUSH_PLANNING_TASK_FORMAT,
    PushPlanningAssessmentSimulator,
    assessment_push_planning_tools,
    configure_assessment_push_planning_task,
    type AssessmentPushPlanningConfig
} from '../src/assessment_push_planning.ts';
import type { AssessmentTask } from '../src/assessment_tasks.ts';

const hardBoard: AssessmentPushPlanningConfig = {
    rows: ['########', '# .  . #', '# #.   #', '#  $$ ##', '# # $#@#', '# #    #', '########']
};
// Independently generated by reverse multi-source BFS (3,109 solvable states), then
// verified by forward BFS (25,113 states discovered before the first 46-move goal).
const hardWitness = [
    'down',
    'left',
    'left',
    'left',
    'up',
    'up',
    'up',
    'down',
    'left',
    'left',
    'up',
    'up',
    'right',
    'right',
    'right',
    'down',
    'right',
    'down',
    'left',
    'left',
    'down',
    'down',
    'right',
    'up',
    'up',
    'right',
    'up',
    'left',
    'up',
    'left',
    'left',
    'left',
    'down',
    'down',
    'right',
    'right',
    'up',
    'down',
    'down',
    'right',
    'up',
    'right',
    'up',
    'left',
    'up',
    'left'
];
const tinyBoard: AssessmentPushPlanningConfig = { rows: ['#####', '# . #', '# $ #', '# @ #', '#####'] };
const inspect = (sim: PushPlanningAssessmentSimulator) => sim.call('inspect_board', {});
const move = (sim: PushPlanningAssessmentSimulator, direction: string) => sim.call('move_player', { direction });
function physical(snapshot: Record<string, unknown>) {
    const { ok, error, ...state } = snapshot;
    return state;
}
function replay(sim: PushPlanningAssessmentSimulator, path: string[]) {
    for (const direction of path) expect(move(sim, direction).ok).toBe(true);
}

/** Independent coordinate/grid transition oracle, used only in tests. */
function boardStep(rows: string[], direction: number): string[] | null {
    if (!rows.some(row => row.includes('$'))) return null;
    const grid = rows.map(row => [...row]),
        shifts = [
            [-1, 0],
            [1, 0],
            [0, -1],
            [0, 1]
        ];
    const row = rows.findIndex(line => line.includes('@') || line.includes('+'));
    const column = rows[row]!.search(/[@+]/),
        [dr, dc] = shifts[direction]!;
    const nr = row + dr!,
        nc = column + dc!,
        next = grid[nr]![nc]!;
    if (next === '#') return null;
    if (next === '$' || next === '*') {
        const br = nr + dr!,
            bc = nc + dc!,
            beyond = grid[br]![bc]!;
        if (![' ', '.'].includes(beyond)) return null;
        grid[br]![bc] = beyond === '.' ? '*' : '$';
        grid[nr]![nc] = next === '*' ? '+' : '@';
    } else grid[nr]![nc] = next === '.' ? '+' : '@';
    grid[row]![column] = grid[row]![column] === '+' ? '.' : ' ';
    return grid.map(line => line.join(''));
}

describe('generic push-only planning simulator', () => {
    test('the independently solved 46-move board reaches its actual goal', () => {
        const sim = new PushPlanningAssessmentSimulator(hardBoard);
        expect(inspect(sim).rows).toEqual(hardBoard.rows);
        replay(sim, hardWitness);
        const state = inspect(sim);
        expect(state).toMatchObject({ moves: 46, status: 'complete' });
        expect(state.pushes).toBeGreaterThan(0);
        expect((state.rows as string[]).join('')).not.toContain('$');
        const report = JSON.stringify({ status: state.status, moves: state.moves, pushes: state.pushes });
        expect(sim.grade(report)).toMatchObject({
            content_score: 1,
            outcome: 'correct',
            tool_checks: { goal_reached: true, observed_board: true, no_invalid_attempts: true, final_report_truthful: true }
        });
        expect(sim.grade('done')).toMatchObject({
            content_score: 1,
            instruction_checks: { json_only: false, exact_fields: false },
            tool_checks: { final_report_truthful: false }
        });
        expect(sim.grade('{"status":"incomplete","moves":0,"pushes":0}')).toMatchObject({
            content_score: 1,
            tool_checks: { final_report_truthful: false }
        });
    });

    test('every small-board state and action matches independent grid reachability', () => {
        const names = ['up', 'down', 'left', 'right'];
        const queue = [{ rows: tinyBoard.rows, path: [] as string[] }],
            seen = new Set([tinyBoard.rows.join('\n')]);
        let transitions = 0,
            goals = 0;
        for (let index = 0; index < queue.length; index++) {
            const state = queue[index]!;
            if (!state.rows.join('').includes('$')) goals++;
            for (let direction = 0; direction < names.length; direction++) {
                const sim = new PushPlanningAssessmentSimulator(tinyBoard);
                replay(sim, state.path);
                const before = physical(inspect(sim));
                const expected = boardStep(state.rows, direction),
                    result = move(sim, names[direction]!);
                expect(result.ok).toBe(expected !== null);
                if (!expected) expect(physical(result)).toEqual(before);
                else {
                    transitions++;
                    expect(result.rows).toEqual(expected);
                    expect(result.moves).toBe(state.path.length + 1);
                    const key = expected.join('\n');
                    if (!seen.has(key)) {
                        seen.add(key);
                        queue.push({ rows: expected, path: [...state.path, names[direction]!] });
                    }
                }
            }
        }
        expect(seen.size).toBeGreaterThan(30);
        expect(transitions).toBeGreaterThan(seen.size);
        expect(goals).toBeGreaterThan(0);
    });

    test('distinct legal routes and arbitrary walking detours earn the same goal credit', () => {
        for (const path of [['up'], ['left', 'right', 'up'], ['right', 'up', 'down', 'left', 'up']]) {
            const sim = new PushPlanningAssessmentSimulator(tinyBoard);
            replay(sim, path);
            expect(inspect(sim)).toMatchObject({ status: 'complete', moves: path.length, pushes: 1 });
            expect(sim.grade(JSON.stringify({ status: 'complete', moves: path.length, pushes: 1 })).content_score).toBe(1);
        }
        const sim = new PushPlanningAssessmentSimulator(tinyBoard);
        for (let i = 0; i < 100; i++) {
            expect(inspect(sim).ok).toBe(true);
            replay(sim, ['left', 'right']);
        }
        replay(sim, ['up']);
        expect(inspect(sim)).toMatchObject({ moves: 201, pushes: 1, status: 'complete' });
    });

    test('walls, consecutive boxes, unsupported tools and malformed arguments reject atomically', () => {
        const config = { rows: ['#######', '# . . #', '# $$@ #', '#######'] };
        const sim = new PushPlanningAssessmentSimulator(config),
            before = physical(inspect(sim));
        const attempts: [string, unknown][] = [
            ['move_player', { direction: 'left' }],
            ['move_player', { direction: 'down' }],
            ['move_player', { direction: 'north' }],
            ['move_player', { direction: 'constructor' }],
            ['move_player', { direction: 1 }],
            ['move_player', {}],
            ['move_player', { direction: 'right', count: 2 }],
            ['inspect_board', { extra: true }],
            ['inspect_board', null],
            ['inspect_board', []],
            ['inspect_board', Object.create({})],
            ['undo', {}],
            ['reset', {}],
            ['pull_box', { direction: 'left' }],
            ['move_player', { direction: () => 'up' }]
        ];
        for (const [name, args] of attempts) {
            const result = sim.call(name, args);
            expect(result.ok).toBe(false);
            expect(physical(result)).toEqual(before);
        }
        expect(move(sim, 'right')).toMatchObject({ ok: true, moves: 1, pushes: 0 });
        const wallPush = new PushPlanningAssessmentSimulator({ rows: ['#####', '#.$@#', '#####'] });
        expect(move(wallPush, 'left')).toMatchObject({ ok: true, pushes: 1, status: 'complete' });
        const blocked = new PushPlanningAssessmentSimulator({ rows: ['######', '#$@ .#', '######'] });
        expect(move(blocked, 'left')).toMatchObject({ ok: false, error: 'box push blocked', moves: 0, pushes: 0 });
    });

    test('a claim or inspections cannot replace execution; reports and invalid attempts remain diagnostic', () => {
        const sim = new PushPlanningAssessmentSimulator(tinyBoard);
        expect(sim.grade('{"status":"complete","moves":1,"pushes":1}')).toMatchObject({
            content_score: 0,
            tool_checks: { used_tools: false, observed_board: false, final_report_truthful: false }
        });
        inspect(sim);
        move(sim, 'down');
        expect(sim.grade('{"status":"incomplete","moves":0,"pushes":0}')).toMatchObject({
            content_score: 0,
            tool_checks: { final_report_truthful: true, no_invalid_attempts: false, used_tools: true, observed_board: true }
        });
        move(sim, 'up');
        expect(sim.grade('{"status":"complete","moves":1,"pushes":1,"extra":true}')).toMatchObject({
            content_score: 1,
            instruction_checks: { exact_fields: false },
            tool_checks: { final_report_truthful: false, no_invalid_attempts: false }
        });
        expect(sim.grade('{"status":"complete","moves":true,"pushes":1}').tool_checks!.final_report_truthful).toBe(false);
        const before = physical(inspect(sim));
        expect(move(sim, 'left')).toMatchObject({ ok: false, error: 'board already complete' });
        expect(physical(inspect(sim))).toEqual(before);
    });

    test('target overlays and initially solved boards follow the physical goal exactly', () => {
        const sim = new PushPlanningAssessmentSimulator({ rows: ['#######', '#+ $  #', '#######'] });
        expect(inspect(sim).rows).toEqual(['#######', '#+ $  #', '#######']);
        replay(sim, ['right', 'right', 'right']);
        expect(inspect(sim)).toMatchObject({ rows: ['#######', '#.  @$#', '#######'], moves: 3, pushes: 2, status: 'incomplete' });
        const solved = new PushPlanningAssessmentSimulator({ rows: ['#####', '#@* #', '#####'] });
        expect(inspect(solved)).toMatchObject({ moves: 0, pushes: 0, status: 'complete' });
        expect(solved.grade('{"status":"complete","moves":0,"pushes":0}')).toMatchObject({
            content_score: 1,
            tool_checks: { final_report_truthful: true }
        });
    });

    test('configurations, responses, histories, schemas and simulator factories are isolated', () => {
        const config = structuredClone(tinyBoard),
            card = { id: 'T2_Push_Planning', kind: 'text' } as AssessmentTask;
        expect(ASSESSMENT_PUSH_PLANNING_TASK_FORMAT).toBe('assessment-push-planning-v1');
        configure_assessment_push_planning_task(card, config);
        config.rows[1] = '#####';
        const first = card.make_simulator!(),
            second = card.make_simulator!();
        const args = { direction: 'left' },
            result = first.call('move_player', args);
        args.direction = 'right';
        (result.rows as string[])[1] = 'corrupted';
        (first.history[0]!.result.rows as string[])[2] = 'corrupted';
        expect(first.history[0]!.arguments).toEqual({ direction: 'left' });
        expect(first.call('inspect_board', {})).toMatchObject({ rows: ['#####', '# . #', '# $ #', '#@  #', '#####'], moves: 1 });
        expect(second.call('inspect_board', {})).toMatchObject({ rows: tinyBoard.rows, moves: 0 });
        expect(card.grade('done')).toMatchObject({ content_score: null, outcome: 'ungradable' });
        const tools = assessment_push_planning_tools();
        expect(tools.map(tool => tool.name)).toEqual(['inspect_board', 'move_player']);
        for (const tool of tools) {
            expect(tool.strict).toBe(true);
            expect((tool.parameters as Record<string, unknown>).additionalProperties).toBe(false);
        }
        expect(tools[1]!.parameters).toMatchObject({
            properties: { direction: { enum: ['up', 'down', 'left', 'right'] } },
            required: ['direction']
        });
        (tools[1]!.parameters as Record<string, unknown>).properties = {};
        expect(assessment_push_planning_tools()[1]!.parameters).toHaveProperty('properties.direction.enum');
    });

    test('validation rejects unsafe, sparse, nonrectangular and inconsistent board data', () => {
        const bad: unknown[] = [
            null,
            [],
            {},
            Object.create(tinyBoard),
            { ...tinyBoard, extra: true },
            { rows: '#####' },
            { rows: [] },
            { rows: new Array(5) },
            { rows: ['###', '#@#', '###'] },
            { rows: ['#####', '#@$ #', '#####'] },
            { rows: ['#####', '#@..#', '#####'] },
            { rows: ['#####', '#@$.#', '####'] },
            { rows: ['#####', '#@$.#', '## ##'] },
            { rows: ['#####', '#@x.#', '#####'] },
            { rows: ['#####', '#@@*#', '#####'] },
            { rows: ['#####', '#$*.#', '#####'] },
            { rows: ['#####', '#@é.#', '#####'] },
            { rows: ['#####', '#@\t.#', '#####'] },
            { rows: ['#'.repeat(33), '#' + '@$.' + ' '.repeat(28) + '#', '#'.repeat(33)] },
            { rows: Array.from({ length: 33 }, () => '#####') },
            { rows: ['##', '@$', '..'] }
        ];
        for (const config of bad) expect(() => new PushPlanningAssessmentSimulator(config)).toThrow('Assessment push planning task');
        expect(() => configure_assessment_push_planning_task({} as AssessmentTask, { rows: ['#'] })).toThrow(
            'Assessment push planning task'
        );
        expect(() => new PushPlanningAssessmentSimulator(tinyBoard)).not.toThrow();
    });
});
